package com.example.rokidgeminisecretary;
public class SpeechTranscriptAccumulatorTest{
 static void eq(String actual,String expected){if(!actual.equals(expected))throw new AssertionError(actual+" != "+expected);}
 public static void main(String[] args){SpeechTranscriptAccumulator a=new SpeechTranscriptAccumulator();a.partial("冒頭の仮");a.partial("冒頭の修正");eq(a.preview(),"冒頭の修正");eq(a.confirmed(),"");a.segment("国立駅");a.partial("赤い");eq(a.preview(),"国立駅 赤い");a.segment("赤い手帳");a.segment("青い傘");eq(a.confirmed(),"国立駅 赤い手帳 青い傘");a.full("青い傘");eq(a.confirmed(),"国立駅 赤い手帳 青い傘");a.full("国立駅 赤い手帳 青い傘。");eq(a.confirmed(),"国立駅 赤い手帳 青い傘。");SpeechTranscriptAccumulator repeat=new SpeechTranscriptAccumulator();repeat.segment("はい");repeat.segment("はい");eq(repeat.confirmed(),"はい はい");if(SpeechTranscriptAccumulator.timeoutMs(16000*2*39,16000)<59000)throw new AssertionError("long timeout");if(SpeechTranscriptAccumulator.timeoutMs(16000*2*60,16000)>90000)throw new AssertionError("unbounded wait");System.out.println("PASS segmented start/middle/end, revised partials, authoritative full result, repeated words and duration-scaled bounded timeout");}}